SELECT d.d_year, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(*) AS return_cnt, AVG(cr.cr_net_loss) AS avg_net_loss_per_return, CASE WHEN SUM(cr.cr_net_loss) > 0 THEN 'LOSS' ELSE 'NO_LOSS' END AS loss_flag, DENSE_RANK() OVER (PARTITION BY ib.ib_income_band_sk ORDER BY SUM(cr.cr_net_loss) DESC) AS net_loss_rank_by_income_band FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN household_demographics hd ON cr.cr_returning_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY d.d_year, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound
